section Section1;
shared Dim_llave_pol_placa = let
  Origen = Sql.Database("wdbanal-dwhp01.hdicolombia.com.co", "Liberty", [Query = "SELECT *#(lf)FROM (select llave_pol, #(lf)nro_placa, #(lf)concat(right(CONCAT('00',cod_marca),3), right(CONCAT('00',cod_clase),2), right(CONCAT('00',cod_tipo),3)) as COD_Fasecolda,#(lf)CAST ((concat(ann_contable,RIGHT(CONCAT('00',mes_contable),2)))AS INT) as PER#(lf)from [Liberty].DT.[DWH_DT_AUT_AUTOS] TABLA1#(lf)WHERE ann_contable >= 1800) as TABLA1#(lf)WHERE PER >= CONVERT(int, FORMAT(DATEADD(month, -1000, GETDATE()), 'yyyyMM'))"])
in
  Origen;
